BEGIN;
INSERT INTO public.exams (slug,title,source,year) VALUES ('espcex-2026-dia-2','EsPCEx 2026 · 2º dia','espcex','2026')
ON CONFLICT (slug) DO UPDATE SET title=excluded.title,source=excluded.source,year=excluded.year;
WITH data AS (SELECT '{"slug": "espcex-2026-dia-2", "source": "espcex", "year": "2026", "title": "EsPCEx 2026 · 2º dia", "questions": [{"number": 1, "subject": "Matemática", "text": "Considere as constantes reais a, b, c, m, q, r e s e a função real definida pela sentença:\nf(x) = 2x² + (s + 1)x + q, se x ≤ 0;\nf(x) = mx + q, se 0 < x < 2;\nf(x) = ax² + bx + c, se x ≥ 2.\nConsidere também o gráfico de f.\nO valor de f(10) é", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q1-figura-1.png", "options": ["27.", "21.", "18.", "24.", "15."], "answer": "B", "explanation": null, "page": 3}, {"number": 2, "subject": "Matemática", "text": "Seja U o conjunto formado por todos os números inteiros pares positivos cuja soma dos algarismos é igual a 6. Considere os seguintes subconjuntos de U: A = {a ∈ U | a < 4 000} e B = {b ∈ U | b tem mais de 4 algarismos}. Seja B̄ = U − B. O número de elementos do conjunto A ∩ B̄ é igual a", "support": null, "support_image": null, "options": ["43.", "47.", "45.", "49.", "41."], "answer": "A", "explanation": null, "page": 3}, {"number": 3, "subject": "Matemática", "text": "Seja A = {x ∈ ℝ | 0 ≤ x ≤ 7}. O conjunto imagem da função f: A → ℝ, tal que y = f(x) = |2x − 6| − x + |x − 3|, é:", "support": null, "support_image": null, "options": ["{y ∈ ℝ | 1 ≤ y ≤ 3}", "{y ∈ ℝ | −2 ≤ y ≤ 3}", "{y ∈ ℝ | −1 ≤ y ≤ 5}", "{y ∈ ℝ | 3 ≤ y ≤ 5}", "{y ∈ ℝ | 0 ≤ y ≤ 5}"], "answer": "C", "explanation": null, "page": 3}, {"number": 4, "subject": "Matemática", "text": "Seja f(x) = 16ˣ, g(x) = 2ˣ e h(x) = (5x − 1)/3. O valor de x tal que f(g(h(x))) = 2 é", "support": null, "support_image": null, "options": ["2.", "–2.", "1.", "–1.", "0."], "answer": "D", "explanation": null, "page": 3}, {"number": 5, "subject": "Matemática", "text": "Dois pelotões, Alfa e Bravo, estão fazendo um treino de\ncorrida, ambos mantendo formação em fila, ou seja, com\nos militares dispostos em coluna, um atrás do outro. No\npelotão Alfa, os militares usam camisas numeradas que\nformam uma progressão aritmética (PA), com o número da\ncamisa do primeiro militar igual a 1, do segundo igual a 4,\ndo terceiro igual a 7, e assim, sucessivamente, até o último\nmilitar. No pelotão Bravo, as camisas também são numeradas e formam a PA 5, 9, 13, 17, ….\nEm certo instante, ambos os pelotões, que correm em sentidos\nopostos em vias retilíneas e paralelas, aproximaram-se de uma\nguarita. O primeiro militar de cada um dos pelotões passou pela\nguarita ao mesmo tempo e, em seguida, para cada 1 militar do\npelotão Alfa que passou pela guarita, passaram 3 militares do\npelotão Bravo.\nNo momento em que o último militar do pelotão Bravo passou\npela guarita, a diferença entre o número de sua camisa e o\nnúmero da camisa do militar do pelotão Alfa que passou ao\nmesmo tempo que ele é igual ao número da camisa do último\nmilitar do pelotão Alfa.\nSabendo que, no momento em que esses dois militares\nestavam passando pela guarita, ainda faltavam passar 19\nmilitares do pelotão Alfa, o número total de militares desses dois pelotões é igual a", "support": null, "support_image": null, "options": ["76.", "114.", "95.", "133.", "57."], "answer": "E", "explanation": null, "page": 3}, {"number": 6, "subject": "Matemática", "text": "No interior do triângulo retângulo ABC foram traçados 7 segmentos paralelos ao lado BC, com extremidades nos lados\nAB e AC, sendo iguais as distâncias entre dois segmentos\nconsecutivos quaisquer e entre o maior desses segmentos e\no lado BC, conforme mostra a figura.\nSabendo que tg α = 2,5 e que a área do quadrilátero DEFG é\n720 cm², a área do triângulo ABC corresponde a", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q6-figura-1.png", "options": ["3 380 cm².", "2 400 cm².", "2 580 cm².", "2 800 cm².", "3 120 cm²."], "answer": "A", "explanation": null, "page": 4}, {"number": 7, "subject": "Matemática", "text": "Considere o seguinte teorema:\nSendo mdc(f, g) o máximo divisor comum entre os polinômios f e g, α é uma raiz comum dos polinômios f e g se, e\nsomente se, α é uma raiz do mdc(f, g).\nAs raízes comuns dos polinômios\nf(x) = 6x⁵ + 49x⁴ – 65x² – 6x + 16 e g(x) = 6x³ – 11x² – 4x + 4\nestão contidas no intervalo:", "support": null, "support_image": null, "options": ["] 2, 5[", "] 5, 8[", "] –7, – 4[", "] –1, 2[", "] – 4, –1["], "answer": "D", "explanation": null, "page": 4}, {"number": 8, "subject": "Matemática", "text": "Sejam a, b, c e d as raízes da equação:\nx⁴ – 15x³ + 20x² + 240x – 576 = 0\nSabendo que a + b = 0, o algarismo das unidades da maior\nraiz dessa equação é", "support": null, "support_image": null, "options": ["1.", "2.", "0.", "3.", "4."], "answer": "B", "explanation": null, "page": 4}, {"number": 9, "subject": "Matemática", "text": "Sobre uma malha quadriculada estão dispostos 35 pontos,\nentre eles os pontos O e F. Um caminho deverá ser traçado\ndo ponto O ao ponto F avançando 10 pontos, um ponto\npor vez, de maneira que o caminho final tenha avançado 4\npontos para cima (C), 3 pontos para a direita (D) e 3 pontos\npara a esquerda (E). O caminho pode passar por F antes de\navançar os 10 pontos, mas obrigatoriamente deve avançar\n10 pontos e terminar em F, o que implica que, em alguns\ncaminhos, um segmento que liga dois pontos consecutivos\npode ser percorrido mais de uma vez. A figura ilustra a malha,\nos 35 pontos e o caminho DDCCCCEEDE.\nNo centro da malha, 9 pontos estão em destaque. O total de\ncaminhos distintos que passam por pelo menos um desses\npontos em destaque é igual a", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q9-figura-1.png", "options": ["4 164.", "2 322.", "2 106.", "3 240.", "3 998."], "answer": "A/B/C/D/E", "explanation": "Questão anulada pela banca após a análise dos recursos. O ponto é atribuído automaticamente.", "page": 4}, {"number": 10, "subject": "Matemática", "text": "Considere a equação logarítmica:\nlog₃(4x + 1) = log₃(x² − 8x + 3) + log₍₁/₃₎(x/5 − 1).\nA única raiz real dessa equação é um número múltiplo de", "support": null, "support_image": null, "options": ["6.", "8.", "7.", "9.", "5."], "answer": "E", "explanation": null, "page": 5}, {"number": 11, "subject": "Matemática", "text": "Um treinamento foi realizado por 420 soldados de determinado\nregimento. Para o transporte desses soldados do quartel até\no local de treinamento, foi utilizado um total de 26 veículos,\nentre caminhões táticos, ônibus e jipes, cada tipo de veículo\ntransportando um número de soldados respectivamente igual\na 20, 24 e 4. A volta de todos para o quartel foi feita utilizando 2\ncaminhões táticos a menos, 1 ônibus a menos e o mesmo número de jipes, cada tipo de veículo transportando um número\nde soldados respectivamente igual a 22, 29 e 6.\nO número total de ônibus e jipes utilizados no transporte de\nida até o local de treinamento é igual a", "support": null, "support_image": null, "options": ["16.", "12.", "15.", "13.", "14."], "answer": "C", "explanation": null, "page": 5}, {"number": 12, "subject": "Matemática", "text": "O cuboctaedro truncado é um poliedro convexo formado por\n26 faces, algumas octógonos regulares, algumas hexágonos\nregulares e as demais quadrados, sendo o número de faces\nquadradas igual ao dobro do número de faces octogonais.\nSe em cada vértice do cuboctaedro concorrem 3 arestas, o\nnúmero de faces hexagonais desse poliedro é igual a", "support": null, "support_image": null, "options": ["6.", "8.", "4.", "3.", "5."], "answer": "B", "explanation": null, "page": 5}, {"number": 13, "subject": "Matemática", "text": "A reta r, de equação 3x – 2y + 18 = 0, intersecta perpendicularmente a reta s, conforme mostra a figura.\nSabendo que a área do triângulo determinado pelas retas\nr e s e pelo eixo x é 39, a reta s intersecta o eixo y no ponto\nde ordenada:", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q13-figura-1.png", "options": ["7/3", "16/3", "14/3", "19/6", "25/6"], "answer": "C", "explanation": null, "page": 5}, {"number": 14, "subject": "Matemática", "text": "Alfredo e Bernardo estão em treinamento de qualificação\npara tiro de 200 m. A probabilidade de Alfredo acertar a área\nde pontuação é 2/3, e a probabilidade de Bernardo acertar a\nárea de pontuação é 5/8. Cada um desses atiradores irá disparar\nduas vezes. A probabilidade de Alfredo acertar a área de\npontuação mais vezes do que Bernardo é:", "support": null, "support_image": null, "options": ["1/3", "1/4", "1/5", "3/5", "5/6"], "answer": "A", "explanation": null, "page": 5}, {"number": 15, "subject": "Matemática", "text": "Dada a matriz M = [(1/4, 3); (−2, 8)], o maior elemento da matriz inversa de M é", "support": null, "support_image": null, "options": ["– 2.", "2.", "– 4.", "1.", "4."], "answer": "D", "explanation": null, "page": 6}, {"number": 16, "subject": "Matemática", "text": "Considere um triângulo ABC e um ponto D sobre o lado BC,\nconforme mostra a figura.\nSabendo que o comprimento do segmento AB é igual ao\ndobro do comprimento do segmento AC, a área do triângulo\nACD corresponde a:", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q16-figura-1.png", "options": ["2√15 cm²", "4√5 cm²", "5√5 cm²", "2√30 cm²", "3√15 cm²"], "answer": "E", "explanation": null, "page": 6}, {"number": 17, "subject": "Matemática", "text": "No plano, um ponto E está sobre o lado BC do quadrilátero\nABCD, conforme mostra a figura.\nSabendo que o lado BC mede 22 cm, que a medida do lado\nCD excede a medida do lado AB em 14 cm e que tg β = 3/5, a\nárea do triângulo ADE é", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q17-figura-1.png", "options": ["144 cm².", "148 cm².", "152 cm².", "136 cm².", "140 cm²."], "answer": "D", "explanation": null, "page": 6}, {"number": 18, "subject": "Matemática", "text": "Em 2025, cada aluno de uma academia de artes marciais participou de exatamente dois torneios: um no Rio de Janeiro (RJ) e\num em São Paulo (SP), mas esses alunos não participaram,\nnecessariamente, dos mesmos torneios. Em abril, cada aluno\nparticipou de um torneio, de maneira que a razão entre o número de alunos que competiram no RJ e o número de alunos que\ncompetiram em SP foi igual a 3/8. Em julho, apenas alguns alunos\nparticiparam de torneios, sendo que 45 alunos competiram no\nRJ e 25 em SP, de tal maneira que, após as competições de\njulho, a razão indicada, considerando o total de participações\naté aquele momento, passou a ser igual a 4/9. Em outubro,\ntodos os alunos com apenas um torneio realizado no ano participaram de mais um.\nO número de alunos dessa academia é igual a", "support": null, "support_image": null, "options": ["649.", "638.", "660.", "627.", "671."], "answer": "E", "explanation": null, "page": 6}, {"number": 19, "subject": "Matemática", "text": "Um cilindro B tem 7 cm de altura e a área de sua base mede o\ndobro da área da base de um cilindro A de altura 8 cm. Sabendo que o volume do cilindro B excede o volume do cilindro A\nem 432π cm³, a área da base do cilindro B é igual", "support": null, "support_image": null, "options": ["121π cm².", "144π cm².", "160π cm².", "196π cm².", "220π cm²."], "answer": "B", "explanation": null, "page": 7}, {"number": 20, "subject": "Matemática", "text": "Os vértices da base de uma pirâmide VCDE estão sobre três\nvértices do quadrado BCDE. A projeção ortogonal do vértice V\nsobre o quadrado BCDE é o ponto H ∈ BD, tal que HD = 3HB,\nconforme mostra a figura.\nSabendo que o volume da pirâmide VCDE é igual a 192 cm³ e\nque a distância entre os pontos H e V é 2,25 vezes a distância\nentre os pontos H e B, a área da face VCE é:", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q20-figura-1.png", "options": ["8√99 cm²", "8√96 cm²", "8√97 cm²", "8√93 cm²", "8√91 cm²"], "answer": "C", "explanation": null, "page": 7}, {"number": 21, "subject": "Geografia", "text": "Examine a seguinte carta topográfica, em que o ponto X\ncorresponde ao local onde um avião caiu, em uma região\nde mata fechada.\n(Raquel Finkler. Planejamento, manejo e gestão de bacias.\nhttps://mid-educacao.curitiba.pr.gov.br. Adaptado.)\nUma equipe de resgate, ao chegar no local da queda, não\nencontrou a caixa-preta do avião. Considerando a leitura\nde cartas topográficas e conhecimentos sobre hidrografia, a\ncaixa-preta será encontrada no ponto", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q21-figura-1.png", "options": ["II.", "III.", "I.", "IV.", "V."], "answer": "C", "explanation": null, "page": 7}, {"number": 22, "subject": "Geografia", "text": "Desde o início de 2025, a Administração Nacional Oceânica e Atmosférica dos Estados Unidos (NOAA) adotou uma\nnova metodologia para identificar um dos fenômenos mais\nimportantes do clima global. O principal motivo para essa\nmudança metodológica é a tendência de aquecimento global.\nComo os oceanos tropicais vêm aquecendo de forma generalizada nas últimas décadas, a nova metodologia passou a\nincorporar esse aquecimento. Ou seja, a nova metodologia\ncomeçou a misturar duas coisas distintas: a variabilidade natural do fenômeno em questão e a tendência de aquecimento de longo prazo associada às mudanças climáticas.\n(Ana Maria Pereira Nunes. www.tempo.com, 03.02.2026. Adaptado.)\nA nova metodologia abordada no excerto é utilizada para\navaliar o fenômeno denominado", "support": null, "support_image": null, "options": ["Chuva ácida.", "Ondas de calor.", "Ilhas de calor.", "Inversão térmica.", "El Niño."], "answer": "E", "explanation": null, "page": 7}, {"number": 23, "subject": "Geografia", "text": "Trata-se da associação de países, em geral de uma mesma região geográfica, que estabelecem relações comerciais\nprivilegiadas entre si e atuam de forma conjunta no mercado\ninternacional.\n(IBGE. Atlas geográfico escolar, 2023. Adaptado.)\nCaracteriza um exemplo de organização internacional descrita\npelo excerto", "support": null, "support_image": null, "options": ["o Mercado Comum do Sul (Mercosul).", "a Organização Internacional do Trabalho (OIT).", "o Grupo dos Sete (G7).", "a Organização do Tratado do Atlântico Norte (Otan).", "a Organização das Nações Unidas (ONU)."], "answer": "A", "explanation": null, "page": 8}, {"number": 24, "subject": "Geografia", "text": "Analise a imagem de uma paisagem urbana.\n(https://blog.ofitexto.com.br)\nA imagem apresenta um problema urbano que tem como\ncaracterística", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q24-figura-1.png", "options": ["a verticalização das cidades, de acordo com a variação do crescimento demográfico.", "a categorização das edificações, de acordo com o nível de segurança construtiva.", "o superávit habitacional, de acordo com a ineficácia de programas habitacionais.", "a fragmentação do espaço geográfico, de acordo com a renda.", "o zoneamento do município, de acordo com a informalidade do mercado de trabalho local."], "answer": "D", "explanation": null, "page": 8}, {"number": 25, "subject": "Geografia", "text": "O gráfico representa um indicador socioeconômico de determinado país.\n(https://maisretorno.com, 05.09.2019. Adaptado.)\nO indicador socioeconômico representado é", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q25-figura-1.png", "options": ["o IDH, e a linha azul corresponde ao crescimento econômico.", "o Coeficiente de Gini, e a área rosa corresponde à desigualdade de renda.", "a Renda per capita, e a linha preta corresponde à renda desse país.", "o PIB, e a linha preta corresponde aos bens produzidos.", "a Cotação de inflação, e a área rosa corresponde ao poder aquisitivo."], "answer": "B", "explanation": null, "page": 8}, {"number": 26, "subject": "Geografia", "text": "Examine a imagem da Serra do Imeri, localizada no norte do\nestado do Amazonas.\n(www.gov.br, 14.03.2024.)\nA imagem apresenta uma forma de relevo classificado como", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q26-figura-1.png", "options": ["cuesta, resultante de processos epirogenéticos.", "residual, resultante de processos erosivos desiguais.", "dobra, resultante de processos divergentes.", "falha, resultante de processos de intemperismo físico.", "falésia, resultante de processos de sedimentação."], "answer": "B", "explanation": null, "page": 9}, {"number": 27, "subject": "Geografia", "text": "Com presença do Exército Brasileiro, o Comando Operacional Conjunto Catrimani II completa dois anos de atuação\ncontínua na terra indígena Yanomami. Ativada em 1o de abril\nde 2024, a operação revela um cenário positivo com o recuo\nhistórico dos índices sob a ação das Forças Armadas. A operação registrou 344 prisões relacionadas a determinada prática\ncriminosa, 191 armamentos apreendidos ou inutilizados, 2 105\nmotores inutilizados e 836 acampamentos destruídos.\n(www.eb.mil.br, 14.04.2026. Adaptado.)\nA Operação Catrimani II na terra indígena Yanomami tem\nauxiliado no combate", "support": null, "support_image": null, "options": ["ao desmatamento ilegal no Cerrado.", "à biopirataria no Pantanal.", "ao garimpo ilegal na Amazônia.", "às queimadas antrópicas na Caatinga.", "ao narcotráfico nos Pampas."], "answer": "C", "explanation": null, "page": 9}, {"number": 28, "subject": "Geografia", "text": "Em 14 de setembro de 1966, o Grupo de Trabalho da\nAmazônia encaminhara ao Presidente Humberto Castelo\nBranco o projeto de lei votado pelo Congresso Nacional que\nresultou na criação de um órgão governamental, a Superintendência do Desenvolvimento da Amazônia (SUDAM). Em\n27 de outubro de 1966, o Presidente Castelo Branco sancionou a lei de incentivo para quem se interessasse na região\namazônica, dispondo sobre a isenção de impostos de renda,\ntaxas federais, atividades industriais, agrícolas, pecuárias e\nde serviços básicos, além da isenção de impostos e taxas\npara importação de máquinas e equipamentos, bem como\npara bens doados por entidades estrangeiras.\n(www.gov.br, 13.10.2020. Adaptado.)\nUm dos objetivos da criação do órgão governamental mencionado no excerto corresponde", "support": null, "support_image": null, "options": ["à integração do território nacional por meio da atração de investimentos para a região amazônica.", "ao incentivo da produção agroflorestal por meio da compra de equipamentos para os povos nativos da Amazônia.", "à expansão da fronteira nacional por meio da aquisição bilateral de áreas da Amazônia peruana.", "ao estímulo ao ciclo da borracha por meio do avanço de estradas de ferro para a região amazônica.", "à instalação de tecnopolos por meio do fomento a pesquisas de inovação tecnológica na Amazônia."], "answer": "A", "explanation": null, "page": 9}, {"number": 29, "subject": "Geografia", "text": "Decreto no 76.593, de 14 de novembro de 1975\nO PRESIDENTE DA REPÚBLICA, usando das atribuições\nque lhe confere o artigo 81, item III, da Constituição,\nDECRETA:\nArt. 1o. Fica instituído o Programa Nacional do Álcool visando ao atendimento das necessidades do mercado interno\ne externo e da política de combustíveis automotivos.\nArt. 2o. A produção do álcool oriundo da cana-de-açúcar,\nda mandioca ou de qualquer outro insumo será incentivada através da expansão da oferta de matérias-primas,\ncom especial ênfase no aumento da produção agrícola, da\nmodernização e ampliação das destilarias existentes e da\ninstalação de novas unidades produtoras, anexas a usinas\nou autônomas, e de unidades armazenadoras.\n(www2.camara.leg.br)\nA decisão política que consta no Decreto no 76.593 caracterizou uma resposta nacional à", "support": null, "support_image": null, "options": ["concorrência dos países sul-americanos no comércio de biocombustíveis.", "crise internacional derivada do esgotamento das reservas de petróleo conhecidas.", "regulação do mercado internacional sobre o uso de combustíveis em países subdesenvolvidos.", "escolha do mercado de combustíveis pela venda preferencial aos países europeus.", "elevação do preço do petróleo no mercado internacional."], "answer": "E", "explanation": null, "page": 10}, {"number": 30, "subject": "Geografia", "text": "A ALZ Grãos — uma joint venture que reúne três gigantes\ndo agronegócio: a brasileira Amaggi, a franco-holandesa Louis\nDreyfus Company (LDC) e a japonesa Zen-Noh — comprou\numa unidade de esmagamento de soja da Fazendão Agronegócio, em Porto Nacional, no Tocantins. A unidade se localiza\nno Distrito Industrial de Luzimangues, às margens da Ferrovia Norte-Sul e conectada ao Arco Norte de exportação, o que\naproxima a produção do grão à etapa de esmagamento, em\nque se obtêm farelo e óleo de soja, e ao envio dos produtos\npelos portos da região. A ALZ opera nove armazéns graneleiros e um terminal portuário no Porto de Itaqui, em São Luís,\nMaranhão, por onde escoa a produção local para o exterior. A\naquisição, que depende de aprovação do Conselho Administrativo de Defesa Econômica (Cade), marca a entrada da ALZ\nGrãos no processamento industrial de soja.\n(Rikardy Tooge. https://investnews.com.br, 16.04.2026. Adaptado.)\nA compra da unidade de esmagamento de soja ocorre no\ncontexto de uma", "support": null, "support_image": null, "options": ["área logística, a chamada Transamazônica.", "Zona Franca, a denominada Cinturão dos Grãos.", "terra devoluta, a chamada Franja Amazônica.", "fronteira agrícola, a chamada Matopiba.", "Unidade de Conservação, a denominada Sealba."], "answer": "D", "explanation": null, "page": 10}, {"number": 31, "subject": "Geografia", "text": "Analise o gráfico que mostra a porcentagem da população\nresidente no Brasil segundo sexo e grupos de idade, em 2010\ne em 2022.\n(https://educa.ibge.gov.br)\nA comparação dos perfis apresentados em 2010 e 2022\nrevela um processo de", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q31-figura-1.png", "options": ["envelhecimento populacional.", "projeção populacional.", "explosão demográfica.", "miscigenação étnica.", "mortalidade infantil."], "answer": "A", "explanation": null, "page": 11}, {"number": 32, "subject": "Geografia", "text": "Analise o mapa do estado do Paraná, que apresenta delimitações territoriais e agrupamentos de municípios.\n(www.amep.pr.gov.br)\nAs áreas destacadas em verde no mapa correspondem a", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q32-figura-1.png", "options": ["cidades médias, cujo objetivo é descentralizar as atividades dos grandes centros urbanos.", "cidades policêntricas, cujo objetivo é alastrar o comércio além do seu centro histórico.", "megacidades, cujo objetivo é centralizar infraestrutura de tecnologia da informação.", "metrópoles, cujo objetivo é concentrar equipamentos urbanos de influência nacional.", "regiões metropolitanas, cujo objetivo é integrar funções públicas de municípios limítrofes."], "answer": "E", "explanation": null, "page": 11}, {"number": 33, "subject": "História", "text": "Os monarcas remuneravam seus servidores e guerreiros\ncom terras, entregando também muitas vezes a imunidade\nsobre elas, isto é, o privilégio de aqueles territórios ficarem\npraticamente isentos de autoridade estatal. O detentor da\nterra desempenhava ali o papel de Estado, taxando, julgando, convocando. Foi assim que a dinastia merovíngia se enfraqueceu de tal forma que cedeu lugar à família latifundiária\ndos carolíngios. No entanto, porque aquele era o condicionamento socioeconômico da época, Pepino e Carlos Magno\ncontinuaram a praticar tal política na Europa católica. Dessa\nforma, os condes foram se apossando de poderes régios e\nimplodindo o Estado carolíngio.\n(Hilário Franco Júnior. A Idade Média: nascimento do Ocidente, 1995.\nAdaptado.)\nSobre o feudalismo, o excerto apresenta a", "support": null, "support_image": null, "options": ["regulamentação do poder sobre um território por meio de transações comerciais.", "relação de dependência pessoal entre reis e soldados firmada por leis escritas.", "fragmentação política com base nas relações de suserania e vassalagem.", "formação da cristandade ocidental fundamentada no poder da Igreja medieval.", "submissão política e militar dos servos da gleba à nobreza guerreira."], "answer": "C", "explanation": null, "page": 12}, {"number": 34, "subject": "História", "text": "O termo “Renascença”, usado para descrever o período\nde cerca de 1330-1530, foi empregado primeiramente por escritores italianos dos séculos XIV e XV que se aperceberam\nda ocorrência de uma mudança fundamental nesse período.\nOs humanistas, a elite intelectual da época, incentivaram uma\npreocupação crescente com a vida cívica, em parte como\nresultado de uma nova visão do homem como um ser compreensível colocado a meio caminho entre Deus e as ordens\ninferiores da natureza.\n(Henry R. Loyn (org.). Dicionário da Idade Média, 1997. Adaptado.)\nCom base no excerto, apreendem-se as seguintes características do Renascimento:", "support": null, "support_image": null, "options": ["o criacionismo e o academicismo.", "o antropocentrismo e o racionalismo.", "o teocentrismo e o naturalismo.", "o realismo e o classicismo.", "o heliocentrismo e o cientificismo."], "answer": "B", "explanation": null, "page": 12}, {"number": 35, "subject": "História", "text": "Analise o mapa de cidades e rotas de comércio do ano de\n1212.\n(Colin McEvedy. Atlas de história medieval, 2007. Adaptado.)\nDe acordo com o mapa, verifica-se que", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q35-figura-1.png", "options": ["os centros urbanos estavam desvinculados das rotas comerciais terrestres e marítimas.", "as rotas terrestres e marítimas do Norte da África eram desconectadas do comércio da península Ibérica.", "a cidade de Constantinopla se colocava como obstáculo ao comércio entre o Ocidente cristão e o Oriente.", "o comércio marítimo europeu se desenvolvia em torno de dois eixos básicos, o mediterrânico e o nórdico.", "as atividades mercantis do Oriente eram restritas às rotas marítimas do mar Vermelho e do oceano Índico."], "answer": "D", "explanation": null, "page": 12}, {"number": 36, "subject": "História", "text": "Os indícios de antipatia entre os criollos e os peninsulares (espanhóis) são por demais específicos para que se possa\nnegá-los e estão por demais disseminados para que se deva\ndesconsiderá-los. A rivalidade entre eles era parte da tensão\nsocial da época. Se os criollos tinham um olho nos seus senhores, mantinham o outro em seus servidores. Os criollos tinham\ntotal consciência da pressão social que vinha de baixo e se\nesforçavam para manter essas pessoas a uma certa distância.\n(John Lynch. “As origens da Independência da América espanhola”.\nIn: Leslie Bethell (org.). História da América Latina: da Independência a 1870,\nvol. III, 2004. Adaptado.)\nNa América espanhola colonial, a estratificação social baseava-se, sobretudo, em critérios", "support": null, "support_image": null, "options": ["patrimoniais e profissionais.", "religiosos e de hereditariedade.", "geográficos e étnico-raciais.", "intelectuais e de linhagem familiar.", "econômicos e de prestígio social."], "answer": "C", "explanation": null, "page": 13}, {"number": 37, "subject": "História", "text": "Após o fracasso da ação na Bahia, a Companhia da Índias\nOcidentais decidiu invadir a capitania de Pernambuco. Vencida a resistência dos colonos luso-brasileiros, os holandeses\nampliaram suas conquistas territoriais. Mauricio de Nassau\nassumiu a administração do “Brasil holandês” ou da “Nova\nHolanda” em 1637 e, para conseguir o apoio dos colonos, ele", "support": null, "support_image": null, "options": ["aboliu a escravidão para modernizar a produção dos engenhos de açúcar.", "estabeleceu o livre comércio do açúcar entre a América e a Europa para ampliar os lucros.", "evitou o domínio sobre colônias portuguesas na África para restringir o tráfico negreiro.", "apoiou a unificação dos Reinos de Portugal e Espanha para a formação da União Ibérica.", "forneceu créditos à elite local para a reconstrução dos engenhos de açúcar."], "answer": "E", "explanation": null, "page": 13}, {"number": 38, "subject": "História", "text": "Analise a pintura do século XVIII, que representa os cercamentos das terras na Grã-Bretanha. Iniciados no século XVI, os\ncercamentos foram intensificados a partir da segunda metade\ndo século XVIII.\n(https://historiaensinoedu.blogspot.com.)\nA pintura retrata uma das condições que favoreceu a Revolução Industrial britânica, porque", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q38-figura-1.png", "options": ["a privatização das terras comuns provocou o êxodo rural e transformou os camponeses em mão de obra para as primeiras fábricas.", "o rearranjo das terras inglesas fixou os camponeses no campo e ampliou a produção de alimentos para as cidades.", "o controle estatal das terras favoreceu o aumento da produção de matérias-primas para as novas fábricas.", "a exploração das minas de carvão foi incrementada nas propriedades privadas e garantiu a fonte de energia nas fábricas.", "o confisco das terras da nobreza pelo Estado permitiu a acumulação de capitais e propiciou as inovações tecnológicas."], "answer": "A", "explanation": null, "page": 13}, {"number": 39, "subject": "História", "text": "Analise a obra Independência ou morte, de Pedro Américo,\nproduzida em 1888. A pintura foi encomendada pelo governo\npaulista para decorar o edifício do Monumento do Ipiranga,\nerguido entre 1885 e 1890.\n(https://enciclopedia.itaucultural.org.br)\nAo representar a Independência do Brasil, ocorrida em 1822,\na obra", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q39-figura-1.png", "options": ["remete ao ato divino da fundação do país com a projeção de uma luz intensa sobre o príncipe regente.", "celebra a memória do príncipe regente como fundador do Império e do Estado nacional brasileiro.", "valoriza a magnitude da ação civil de libertação do país em detrimento do papel da Cavalaria, representada ao fundo da tela.", "enaltece o Império no auge de suas conquistas militares lideradas pelo príncipe e financiadas pela riqueza do ouro e do café.", "idealiza a emancipação política como confraternização entre o príncipe e uma multidão de paulistas."], "answer": "B", "explanation": null, "page": 14}, {"number": 40, "subject": "História", "text": "Leia o discurso do ministro do Exterior Bernhard von Bülow,\nproferido no parlamento alemão em 6 de dezembro de 1897.\nOs dias em que os alemães concediam a terra a um vizinho, a outro o mar e reservavam para si o céu, onde reina\na doutrina pura — esses dias chegaram ao fim. A nosso ver,\né tarefa primordial fomentar e cultivar os interesses da nossa\nmarinha, nosso comércio e nossa indústria, principalmente\nno Oriente. [...]\nFicamos felizes de respeitar os interesses de outras potências na China, desde que tenhamos a certeza de que os\nnossos interesses também receberão o reconhecimento que\nmerecem. Em suma, não queremos fazer sombra a ninguém,\nmas também exigimos nosso lugar ao sol.\n(Apud Lawrence Sondhaus. A Primeira Guerra Mundial, 2017.)\nNo contexto que antecede a Primeira Guerra Mundial, esse\ndiscurso exemplifica as", "support": null, "support_image": null, "options": ["disputas por esferas de influência entre as potências imperialistas.", "rivalidades franco-germânicas decorrentes da Guerra da Prússia.", "formações de alianças político-militares entre os países europeus.", "tensões nacionalistas entre os povos recém-independentes da região balcânica.", "intenções das potências industrializadas de modernizarem seu arsenal militar."], "answer": "A", "explanation": null, "page": 14}, {"number": 41, "subject": "História", "text": "Nas eleições presidenciais de 1922, os estados da Bahia,\nPernambuco, Rio Grande do Sul e Rio de Janeiro formaram\na Reação Republicana, que apresentou o candidato Nilo Peçanha para disputar contra Artur Bernardes, candidato a presidente indicado por São Paulo e Minas Gerais. O programa da\nReação Republicana baseava-se no controle da inflação e na\ndefesa de finanças equilibradas para o Estado brasileiro. Ela\ntambém reivindicava uma política econômica que protegesse\nas mercadorias nacionais de exportação em geral, sem privilégios a qualquer produto em particular.\nNo contexto da República Velha, a Reação Republicana", "support": null, "support_image": null, "options": ["apresentou um plano de valorização do café para alcançar uma balança de comércio favorável para o país.", "reafirmou a aliança oligárquica, promovida pela política dos governadores nas eleições legislativas nacionais.", "apoiou uma revisão constitucional para limitar a autonomia estadual e ampliar a centralização política na capital federal.", "colaborou para a adoção do voto secreto nas eleições presidenciais em consonância ao movimento tenentista da época.", "representou uma dissidência de estados de grande importância eleitoral contra a chamada política do café com leite."], "answer": "E", "explanation": null, "page": 15}, {"number": 42, "subject": "História", "text": "Analise a fotografia que mostra pracinhas da Força Expedicionária Brasileira (FEB) reunidos no navio General Mann\nem 1944.\n(https://aventurasnahistoria.com.br. Adaptado.)\nNo contexto da Segunda Guerra Mundial, a FEB", "support": null, "support_image": "/militares-2026/espcex-2026-dia-2-q42-figura-1.png", "options": ["representou o alinhamento político e militar do governo brasileiro às forças armadas das potências do Eixo.", "assegurou a colaboração brasileira no transporte de materiais estratégicos, como a borracha, para a zona europeia de conflito.", "resultou de uma imposição dos Aliados para integrar as tropas brasileiras aos combates nas frentes europeia e asiática.", "concretizou o enquadramento de forças militares brasileiras ao lado da frente antifascista na Europa.", "promoveu a instalação de bases militares estadunidenses no Nordeste brasileiro para patrulhar o Atlântico contra os inimigos."], "answer": "D", "explanation": null, "page": 15}, {"number": 43, "subject": "História", "text": "Em abril de 1955, representantes de vinte e nove governos de nações asiáticas e africanas reuniram-se em Bandung,\nna Indonésia. Os princípios fundamentais da Conferência de\nBandung foram a autodeterminação política, o respeito mútuo pela soberania, a não agressão, a não interferência em\nassuntos internos e a igualdade.\n(https://history.state.gov. Adaptado.)\nDurante a Guerra Fria, a Conferência de Bandung", "support": null, "support_image": null, "options": ["contribuiu para a estabilidade dos Estados da região e para a ascensão do neoliberalismo.", "significou um marco na luta anticolonial e na criação do bloco de países não-alinhados.", "determinou a desmilitarização dos países recém-independentes do continente asiático.", "representou um esforço regional em defesa da não proliferação das armas nucleares.", "definiu as áreas de influência das duas superpotências no continente africano."], "answer": "B", "explanation": null, "page": 15}, {"number": 44, "subject": "História", "text": "O Plano de Metas do governo de Juscelino Kubitschek\n(1956-1961) previa um desenvolvimento acelerado do país\nsob o slogan “50 anos em 5”. Os resultados do Plano de\nMetas foram expressivos, principalmente no que diz respeito à produção industrial, que cresceu cerca de 80% nesse\nperíodo. As medidas do Plano de Metas", "support": null, "support_image": null, "options": ["defendiam a contenção de gastos públicos a fim de reduzir o déficit fiscal.", "promoviam a desestatização da economia brasileira com a adoção do liberalismo.", "propunham reformas estruturais, como a agrária, para combater a desigualdade social.", "integravam investimentos estatais a capitais privados nacionais e estrangeiros.", "buscavam combater a alta da inflação com juros altos para reduzir a demanda."], "answer": "D", "explanation": null, "page": 15}, {"number": 45, "subject": "Língua Inglesa", "text": "The campaign poster primarily encourages consumers to", "support": "Read the poster for a campaign launched by an organization\nin the United Kingdom to answer questions from 45 to 47.\n(https://actiononsugar.org, 2025. Adaptado.)\n1 sweet talk: persuasive language.", "support_image": "/militares-2026/espcex-2026-dia-2-apoio-16-figura-1.png", "options": ["buy products with sweeteners whenever possible.", "persuade manufacturers to improve their products.", "ignore deceptive marketing to see the truth.", "add more protein to their daily diet.", "trust the claims written on food labels."], "answer": "C", "explanation": null, "page": 16}, {"number": 46, "subject": "Língua Inglesa", "text": "The phrase from the poster “Needlessly high in protein”\nindicates that protein", "support": "Read the poster for a campaign launched by an organization\nin the United Kingdom to answer questions from 45 to 47.\n(https://actiononsugar.org, 2025. Adaptado.)\n1 sweet talk: persuasive language.", "support_image": "/militares-2026/espcex-2026-dia-2-apoio-16-figura-1.png", "options": ["should be consumed in appropriate amounts.", "might be tastier than all the other nutrients.", "should be consumed in unlimited quantities.", "can be harmful when eaten in small amounts.", "must be the main part of every meal."], "answer": "A", "explanation": null, "page": 16}, {"number": 47, "subject": "Língua Inglesa", "text": "The sentence from the poster “Isn’t it time food labels told the\nwhole story?” is questioning whether", "support": "Read the poster for a campaign launched by an organization\nin the United Kingdom to answer questions from 45 to 47.\n(https://actiononsugar.org, 2025. Adaptado.)\n1 sweet talk: persuasive language.", "support_image": "/militares-2026/espcex-2026-dia-2-apoio-16-figura-1.png", "options": ["food companies use just natural ingredients in their products.", "sugary foods deserve a complete ban from people’s diets.", "some natural ingredients are harmful to people’s health.", "protein bars are tasty even with artificial ingredients.", "food companies’ marketing strategies produce misleading labels."], "answer": "E", "explanation": null, "page": 16}, {"number": 48, "subject": "Língua Inglesa", "text": "The text mainly aims at", "support": "Leia o texto para responder às questões de 48 a 54.\n1 Brazilian Army Colonel Sergio Reis Matos serves as one\nof four United States Army South’s (USARSOUTH) partner\nnation liaison officers, or PNLO. Since July 2023, Matos has\nworked to strengthen the historic partnership between Brazil\nand the United States (US), focusing on enhancing military\ncollaboration and interoperability.\nMatos’ journey into the military began with two key\ninfluences: his father, a decorated non-commissioned officer\nin the Brazilian Navy, and his own early experience at a\nmilitary middle school. “My father earned the rank of sergeant\nmajor and was able to travel the world to 23 countries,” said\nMatos. “He was a brilliant example of the opportunities to be\nhad by serving my homeland.”\nIn 1987, Matos was accepted into a military middle schoo\nwhich was overseen by the Brazilian Army, which Matos said\nis very similar to the junior reserve officers’ training corps. His\nexperience there laid the foundation for values and discipline\nneeded for a career in the army.\nMatos began his military career in 1993 at the Brazilian\nArmy Cadets’ Preparatory School in São Paulo. Over nearly\n32 years, he has held several distinguished roles, including\ncommanding a border detachment in the Amazon, securing\nmilitary venues during the 2016 Olympic Games in Brazil and\nleading an infantry battalion steeped in historical ties to the\nUS Fifth Army. “The most memorable period of my career was\nwhen I commanded the 11th Mountain Infantry Battalion,”\nhe reflected. “It was one of the units that integrated with US\nforces during World War II.”\n5 His assignment as the Brazilian PNLO at USARSOUTH is\nnot his first encounter with the US Army. In 2007, he attended\nthe Captain’s Career Course at Fort Moore (US) where he\nearned the Distinguished International Honor Graduate award\nfor excellence in academics and the Order of Saint Maurice\nMedallion in the rank of Peregrinus, for his notable contributions\nto the US infantry.\nDuring his tenure at USARSOUTH, he facilitated military\ncoordination between the Brazilian and US armies, focusing\non combined operations, joint exercises and strategic\nengagements. His efforts as the Brazilian PNLO have been\ncentral to enhancing interoperability and fostering deeper\ncollaboration.\n(Joshua Taeckens. www.army.mil, 11.01.2025. Adaptado.)", "support_image": "/militares-2026/espcex-2026-dia-2-apoio-17-figura-1.png", "options": ["evaluating the effectiveness of international military partnerships.", "explaining how the Brazilian army and the US army operate.", "presenting Colonel Matos’ military career and professional achievements.", "questioning current standards of military cooperation between allied nations.", "encouraging greater investment in military education and training programs."], "answer": "C", "explanation": null, "page": 17}, {"number": 49, "subject": "Língua Inglesa", "text": "No trecho do primeiro parágrafo “Since July 2023”, o termo\nsublinhado é empregado com o mesmo sentido do termo\nsublinhado em:", "support": "Leia o texto para responder às questões de 48 a 54.\n1 Brazilian Army Colonel Sergio Reis Matos serves as one\nof four United States Army South’s (USARSOUTH) partner\nnation liaison officers, or PNLO. Since July 2023, Matos has\nworked to strengthen the historic partnership between Brazil\nand the United States (US), focusing on enhancing military\ncollaboration and interoperability.\nMatos’ journey into the military began with two key\ninfluences: his father, a decorated non-commissioned officer\nin the Brazilian Navy, and his own early experience at a\nmilitary middle school. “My father earned the rank of sergeant\nmajor and was able to travel the world to 23 countries,” said\nMatos. “He was a brilliant example of the opportunities to be\nhad by serving my homeland.”\nIn 1987, Matos was accepted into a military middle schoo\nwhich was overseen by the Brazilian Army, which Matos said\nis very similar to the junior reserve officers’ training corps. His\nexperience there laid the foundation for values and discipline\nneeded for a career in the army.\nMatos began his military career in 1993 at the Brazilian\nArmy Cadets’ Preparatory School in São Paulo. Over nearly\n32 years, he has held several distinguished roles, including\ncommanding a border detachment in the Amazon, securing\nmilitary venues during the 2016 Olympic Games in Brazil and\nleading an infantry battalion steeped in historical ties to the\nUS Fifth Army. “The most memorable period of my career was\nwhen I commanded the 11th Mountain Infantry Battalion,”\nhe reflected. “It was one of the units that integrated with US\nforces during World War II.”\n5 His assignment as the Brazilian PNLO at USARSOUTH is\nnot his first encounter with the US Army. In 2007, he attended\nthe Captain’s Career Course at Fort Moore (US) where he\nearned the Distinguished International Honor Graduate award\nfor excellence in academics and the Order of Saint Maurice\nMedallion in the rank of Peregrinus, for his notable contributions\nto the US infantry.\nDuring his tenure at USARSOUTH, he facilitated military\ncoordination between the Brazilian and US armies, focusing\non combined operations, joint exercises and strategic\nengagements. His efforts as the Brazilian PNLO have been\ncentral to enhancing interoperability and fostering deeper\ncollaboration.\n(Joshua Taeckens. www.army.mil, 11.01.2025. Adaptado.)", "support_image": "/militares-2026/espcex-2026-dia-2-apoio-17-figura-1.png", "options": ["Since you are the manager, you must decide which strategy is best for the team.", "Since there is no more fuel, the pilot will have to perform an emergency landing.", "Since you asked me to, I will complete the reports and send them immed